class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.hinge_loss = nn.Parameter(torch.zeros(1, 1))
        self.predictions = nn.Parameter(torch.zeros(batch_size, dim), requires_grad=True)
        self.targets = nn.Parameter(torch.ones(batch_size, dim), requires_grad=True)

    def forward(self, predictions, targets):
        # Compute hinge loss using custom CUDA operator
        # Hinge Loss: max(0, 1 - p * t) for binary classification
        # We'll implement a custom CUDA kernel for element-wise multiplication and clamping

        # Custom CUDA kernel for hinge loss computation
        def hinge_loss_kernel(inputs):
            size = inputs.numel()
            block_size = 256
            num_blocks = (size + block_size - 1) // block_size

            # Initialize output tensor
            out = torch.zeros_like(inputs)

            # Compute element-wise multiplication and clamping
            for i in range(num_blocks):
                start_idx = i * block_size
                end_idx = min((i + 1) * block_size, size)

                # Load input values
                a = inputs.data_ptr<float>()
                b = torch.clamp(inputs[i] * targets[i], min=0.0)

                # Compute hinge loss: max(0, 1 - p * t)
                out[start_idx:end_idx] = torch.max(0, 1 - b * targets[i])

            return out

        # Compile the custom CUDA kernel
        elementwise_hinge_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = torch.max(0.0, 1.0 - b[idx] * targets[idx]);
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hinge_loss_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

